insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Belajar Topik dari Nol','belajar-topik-dari-nol','Belajar','Jelaskan satu topik dari dasar dengan analogi, contoh, latihan, dan kuis.','Saya ingin belajar [TOPIK]. Tingkat saya saat ini: [TINGKAT_SAAT_INI]. Ajarkan dari dasar dengan urutan: konsep inti, analogi sederhana, contoh nyata, 3 kesalahan umum, latihan singkat, lalu kuis 5 soal. Jangan lanjut ke bagian berikutnya sebelum fondasi konsepnya jelas.','ChatGPT','chatgpt','Pemula',ARRAY['TOPIK','TINGKAT_SAAT_INI']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','belajar']::text[],'[]'::jsonb,false,'draft','Belajar Topik dari Nol — Prompt AI Siap Salin | AIUpdateId','Jelaskan satu topik dari dasar dengan analogi, contoh, latihan, dan kuis.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Tutor Socratic','tutor-socratic','Belajar','Belajar lewat pertanyaan bertahap tanpa langsung diberi semua jawaban.','Bertindak sebagai tutor Socratic untuk [TOPIK]. Tujuan saya: [TUJUAN]. Jangan langsung memberi jawaban final. Ajukan satu pertanyaan pada satu waktu, nilai jawaban saya, beri petunjuk bila perlu, lalu bantu saya menemukan jawabannya sendiri. Di akhir, rangkum konsep yang sudah saya pahami dan yang masih perlu dilatih.','Claude','claude','Menengah',ARRAY['TOPIK','TUJUAN']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','belajar']::text[],'[]'::jsonb,false,'draft','Tutor Socratic — Prompt AI Siap Salin | AIUpdateId','Belajar lewat pertanyaan bertahap tanpa langsung diberi semua jawaban.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Buat Flashcard Belajar','buat-flashcard-belajar','Belajar','Mengubah materi menjadi flashcard ringkas untuk latihan aktif.','Ubah materi berikut menjadi [JUMLAH] flashcard belajar. Format setiap kartu: Pertanyaan | Jawaban singkat | Penjelasan 1 kalimat | Tingkat kesulitan. Prioritaskan konsep yang paling penting dan hindari pertanyaan yang jawabannya terlalu mudah ditebak. Materi: [MATERI]','ChatGPT','chatgpt','Pemula',ARRAY['MATERI','JUMLAH']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','belajar']::text[],'[]'::jsonb,false,'draft','Buat Flashcard Belajar — Prompt AI Siap Salin | AIUpdateId','Mengubah materi menjadi flashcard ringkas untuk latihan aktif.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Kuis Pemahaman Bertingkat','kuis-pemahaman-bertingkat','Belajar','Menguji pemahaman dari mudah sampai analitis.','Buat kuis tentang [TOPIK] sebanyak 12 soal: 4 dasar, 4 aplikasi, 4 analisis. Jangan tampilkan jawabannya dulu. Setelah saya menjawab, nilai satu per satu, jelaskan kesalahan secara singkat, lalu berikan skor dan rekomendasi bagian yang perlu dipelajari ulang.','Gemini','gemini','Pemula',ARRAY['TOPIK']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','belajar']::text[],'[]'::jsonb,false,'draft','Kuis Pemahaman Bertingkat — Prompt AI Siap Salin | AIUpdateId','Menguji pemahaman dari mudah sampai analitis.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Rencana Belajar 14 Hari','rencana-belajar-14-hari','Belajar','Menyusun jadwal belajar realistis selama dua minggu.','Buat rencana belajar 14 hari untuk [TOPIK]. Waktu tersedia [WAKTU_PER_HARI] per hari dan tujuan saya [TUJUAN]. Bagi menjadi target harian realistis, materi inti, latihan, review berkala, dan checkpoint pada hari 7 dan 14. Jangan membuat jadwal terlalu padat.','ChatGPT','chatgpt','Pemula',ARRAY['TOPIK','WAKTU_PER_HARI','TUJUAN']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','belajar']::text[],'[]'::jsonb,false,'draft','Rencana Belajar 14 Hari — Prompt AI Siap Salin | AIUpdateId','Menyusun jadwal belajar realistis selama dua minggu.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Kerangka Artikel SEO','kerangka-artikel-seo','Menulis','Membuat kerangka artikel yang fokus pada intent pembaca dan struktur SEO.','Buat kerangka artikel SEO untuk keyword [KEYWORD], target pembaca [AUDIENS], tujuan artikel [TUJUAN]. Tentukan search intent, sudut pembahasan, H1, struktur H2/H3, pertanyaan FAQ, ide internal link, dan bagian yang membutuhkan data atau sumber. Hindari heading generik yang tidak memberi nilai tambah.','ChatGPT','chatgpt','Pemula',ARRAY['KEYWORD','AUDIENS','TUJUAN']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','menulis']::text[],'[]'::jsonb,false,'draft','Kerangka Artikel SEO — Prompt AI Siap Salin | AIUpdateId','Membuat kerangka artikel yang fokus pada intent pembaca dan struktur SEO.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Editor Tulisan Profesional','editor-tulisan-profesional','Menulis','Memperjelas tulisan tanpa mengubah makna utama.','Edit teks berikut agar lebih jelas, alami, profesional, dan sesuai gaya [GAYA]. Pertahankan makna utama, buang pengulangan, perbaiki alur, dan tandai klaim yang perlu diverifikasi. Setelah versi revisi, jelaskan maksimal 5 perubahan terpenting. Teks: [TEKS]','Claude','claude','Pemula',ARRAY['TEKS','GAYA']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','menulis']::text[],'[]'::jsonb,false,'draft','Editor Tulisan Profesional — Prompt AI Siap Salin | AIUpdateId','Memperjelas tulisan tanpa mengubah makna utama.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Buat 10 Judul Menarik','buat-10-judul-menarik','Menulis','Menghasilkan variasi judul tanpa clickbait berlebihan.','Buat 10 judul untuk topik [TOPIK] dengan target [AUDIENS]. Kelompokkan menjadi: informatif, rasa ingin tahu, manfaat langsung, dan perbandingan. Judul harus spesifik, tidak menyesatkan, dan maksimal sekitar 70 karakter jika memungkinkan.','ChatGPT','chatgpt','Pemula',ARRAY['TOPIK','AUDIENS']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','menulis']::text[],'[]'::jsonb,false,'draft','Buat 10 Judul Menarik — Prompt AI Siap Salin | AIUpdateId','Menghasilkan variasi judul tanpa clickbait berlebihan.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Ubah Catatan Menjadi Artikel','ubah-catatan-menjadi-artikel','Menulis','Mengubah catatan kasar menjadi artikel yang mengalir.','Ubah catatan berikut menjadi artikel sekitar [PANJANG] untuk [AUDIENS]. Buat pembuka yang relevan, alur logis, contoh nyata, tips praktis, kesalahan umum, ringkasan inti, dan FAQ. Jangan menambahkan fakta spesifik yang tidak ada di catatan tanpa menandainya untuk verifikasi. Catatan: [CATATAN]','Claude','claude','Menengah',ARRAY['CATATAN','AUDIENS','PANJANG']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','menulis']::text[],'[]'::jsonb,false,'draft','Ubah Catatan Menjadi Artikel — Prompt AI Siap Salin | AIUpdateId','Mengubah catatan kasar menjadi artikel yang mengalir.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Ringkas Artikel Panjang','ringkas-artikel-panjang','Menulis','Meringkas teks panjang tanpa kehilangan poin utama.','Ringkas teks berikut menjadi: 5 poin inti, fakta/data penting, keputusan atau kesimpulan, hal yang belum pasti, dan ringkasan 100 kata. Jangan memasukkan informasi yang tidak ada di teks. Teks: [TEKS]','Gemini','gemini','Pemula',ARRAY['TEKS']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','menulis']::text[],'[]'::jsonb,false,'draft','Ringkas Artikel Panjang — Prompt AI Siap Salin | AIUpdateId','Meringkas teks panjang tanpa kehilangan poin utama.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Ringkas Jurnal Akademik','ringkas-jurnal-akademik','Mahasiswa','Membantu memahami struktur dan temuan jurnal tanpa menggantikan pembacaan sumber.','Analisis jurnal berikut dan jelaskan: pertanyaan penelitian, metode, sampel/data, temuan utama, keterbatasan, implikasi, dan 5 istilah penting. Bedakan dengan jelas antara apa yang dinyatakan penulis dan interpretasi Anda. Jangan membuat sitasi yang tidak tersedia. Jurnal: [TEKS_JURNAL]','NotebookLM','notebooklm','Menengah',ARRAY['TEKS_JURNAL']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','mahasiswa']::text[],'[]'::jsonb,true,'draft','Ringkas Jurnal Akademik — Prompt AI Siap Salin | AIUpdateId','Membantu memahami struktur dan temuan jurnal tanpa menggantikan pembacaan sumber.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Buat Pertanyaan Diskusi Kuliah','pertanyaan-diskusi-kuliah','Mahasiswa','Membuat pertanyaan diskusi yang lebih analitis.','Berdasarkan materi [MATERI], buat 10 pertanyaan diskusi kuliah: 3 pemahaman, 3 aplikasi, 3 analisis, dan 1 pertanyaan debat. Sertakan alasan singkat mengapa setiap pertanyaan penting, tetapi jangan berikan jawaban final.','ChatGPT','chatgpt','Pemula',ARRAY['MATERI']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','mahasiswa']::text[],'[]'::jsonb,false,'draft','Buat Pertanyaan Diskusi Kuliah — Prompt AI Siap Salin | AIUpdateId','Membuat pertanyaan diskusi yang lebih analitis.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Cek Logika Argumen','cek-logika-argumen','Mahasiswa','Mengulas kekuatan dan kelemahan argumen akademik.','Tinjau argumen berikut secara kritis. Identifikasi klaim utama, bukti pendukung, asumsi tersembunyi, lompatan logika, kemungkinan bias, dan counterargument yang masuk akal. Jangan menilai berdasarkan apakah Anda setuju; nilai struktur alasannya. Argumen: [ARGUMEN]','Claude','claude','Menengah',ARRAY['ARGUMEN']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','mahasiswa']::text[],'[]'::jsonb,false,'draft','Cek Logika Argumen — Prompt AI Siap Salin | AIUpdateId','Mengulas kekuatan dan kelemahan argumen akademik.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Analisis Ide Bisnis UMKM','analisis-ide-bisnis-umkm','Bisnis & UMKM','Menguji ide bisnis secara terstruktur sebelum mengeluarkan banyak biaya.','Analisis ide bisnis [IDE_BISNIS] untuk lokasi [LOKASI] dan target pelanggan [TARGET]. Bahas masalah pelanggan, value proposition, pesaing, cara validasi murah, estimasi komponen biaya, risiko, channel penjualan, dan 7 pertanyaan yang harus saya jawab sebelum mulai. Jangan mengarang angka pasar; tandai data yang perlu dicari.','ChatGPT','chatgpt','Pemula',ARRAY['IDE_BISNIS','LOKASI','TARGET']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','bisnis & umkm']::text[],'[]'::jsonb,true,'draft','Analisis Ide Bisnis UMKM — Prompt AI Siap Salin | AIUpdateId','Menguji ide bisnis secara terstruktur sebelum mengeluarkan banyak biaya.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Persona Pelanggan UMKM','persona-pelanggan-umkm','Bisnis & UMKM','Membuat hipotesis persona untuk diuji dengan pelanggan nyata.','Buat 3 hipotesis persona pelanggan untuk produk [PRODUK] dengan target awal [TARGET_AWAL]. Untuk tiap persona: kebutuhan, masalah, motivasi, keberatan membeli, pemicu pembelian, channel yang mungkin digunakan, dan 5 pertanyaan wawancara validasi. Tegaskan bahwa persona ini hipotesis yang perlu diuji.','Gemini','gemini','Pemula',ARRAY['PRODUK','TARGET_AWAL']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','bisnis & umkm']::text[],'[]'::jsonb,false,'draft','Persona Pelanggan UMKM — Prompt AI Siap Salin | AIUpdateId','Membuat hipotesis persona untuk diuji dengan pelanggan nyata.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Ide Promo Tanpa Diskon Besar','ide-promo-tanpa-diskon-besar','Bisnis & UMKM','Mencari promosi yang tidak hanya mengandalkan potongan harga.','Buat 12 ide promosi untuk [BISNIS] yang menjual [PRODUK] kepada [TARGET], dengan syarat tidak bergantung pada diskon besar. Gunakan bundling, bonus, referral, urgency yang jujur, edukasi, komunitas, dan repeat order. Untuk setiap ide, tulis mekanisme, manfaat, risiko, dan metrik sederhana untuk mengevaluasinya.','ChatGPT','chatgpt','Pemula',ARRAY['BISNIS','PRODUK','TARGET']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','bisnis & umkm']::text[],'[]'::jsonb,false,'draft','Ide Promo Tanpa Diskon Besar — Prompt AI Siap Salin | AIUpdateId','Mencari promosi yang tidak hanya mengandalkan potongan harga.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Kalender Konten 30 Hari','kalender-konten-30-hari','Marketing','Membuat rencana konten bulanan yang terstruktur.','Buat kalender konten 30 hari untuk [BRAND], audiens [AUDIENS], platform [PLATFORM], tujuan [TUJUAN]. Untuk tiap hari tulis: tema, hook, format, poin isi, CTA, dan tujuan funnel. Seimbangkan edukasi, bukti, interaksi, penawaran, dan storytelling; jangan membuat 30 postingan yang terasa sama.','ChatGPT','chatgpt','Menengah',ARRAY['BRAND','AUDIENS','PLATFORM','TUJUAN']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','marketing']::text[],'[]'::jsonb,true,'draft','Kalender Konten 30 Hari — Prompt AI Siap Salin | AIUpdateId','Membuat rencana konten bulanan yang terstruktur.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Analisis Kompetitor Konten','analisis-kompetitor-konten','Marketing','Membandingkan strategi konten dengan data yang pengguna berikan.','Analisis data kompetitor berikut untuk [BRAND]. Kelompokkan pola tema, format, hook, CTA, positioning, kekuatan, kelemahan, dan peluang diferensiasi. Jangan menganggap engagement tinggi berarti strategi pasti efektif tanpa konteks. Data kompetitor: [DATA_KOMPETITOR]','Claude','claude','Menengah',ARRAY['DATA_KOMPETITOR','BRAND']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','marketing']::text[],'[]'::jsonb,false,'draft','Analisis Kompetitor Konten — Prompt AI Siap Salin | AIUpdateId','Membandingkan strategi konten dengan data yang pengguna berikan.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Jelaskan Kode untuk Pemula','jelaskan-kode-untuk-pemula','Coding','Membantu memahami kode langkah demi langkah.','Jelaskan kode [BAHASA] berikut untuk pemula. Uraikan tujuan keseluruhan, alur eksekusi, fungsi setiap bagian penting, input/output, potensi bug, dan contoh perubahan kecil yang aman untuk latihan. Jangan hanya memparafrase setiap baris. Kode: [KODE]','GitHub Copilot','github-copilot','Pemula',ARRAY['KODE','BAHASA']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','coding']::text[],'[]'::jsonb,false,'draft','Jelaskan Kode untuk Pemula — Prompt AI Siap Salin | AIUpdateId','Membantu memahami kode langkah demi langkah.') on conflict (slug) do nothing;
insert into public.ai_prompts (title,slug,category,description,prompt_text,tool_name,tool_slug,level,variables,tips,tags,faq,featured,status,seo_title,meta_description) values ('Debug dengan Hipotesis','debug-dengan-hipotesis','Coding','Menganalisis bug dengan urutan hipotesis dan verifikasi.','Bantu debug masalah berikut. Konteks: [KONTEKS]. Error: [ERROR]. Kode: [KODE]. Buat maksimal 5 hipotesis penyebab yang diurutkan dari paling mungkin, jelaskan bukti yang mendukung/menolak, lalu berikan langkah verifikasi paling aman untuk tiap hipotesis sebelum menyarankan perubahan kode.','GitHub Copilot','github-copilot','Menengah',ARRAY['ERROR','KODE','KONTEKS']::text[],ARRAY['Tambahkan konteks yang spesifik.','Periksa fakta penting sebelum digunakan.','Minta revisi jika hasil pertama belum sesuai.']::text[],ARRAY['prompt ai','coding']::text[],'[]'::jsonb,true,'draft','Debug dengan Hipotesis — Prompt AI Siap Salin | AIUpdateId','Menganalisis bug dengan urutan hipotesis dan verifikasi.') on conflict (slug) do nothing;
